 static class Program {
  public static bool Rendering;
  [STAThread] static void Main(string[] args){Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);Application.ThreadException+=(s,e)=>UI.Error(e.Exception);try{
   var modules=Catalog.Load();
   if(args.Length>2&&args[0]=="/render-config"){Rendering=true;var m=modules.Find(x=>x.Name==args[2]);UI.Render(new FloatingControls(m,null,null),args[1]);return;}
   if(args.Length>1&&args[0]=="/integration-test"){WindowsSaver.SelfTest(args[1]);return;}
   if(args.Length>0&&args[0]=="/register"){WindowsSaver.Configure(Paths.Root,Paths.Int(Paths.Modern,"Enabled",1)!=0,WindowsSaver.Seconds());return;}
   if(args.Length>0 && args[0]=="/selftest"){var errors=new List<string>();int controls=0,choices=0;foreach(var m in modules){if(!File.Exists(Path.Combine(Paths.Root,"After Dark 4.0",m.File)))errors.Add(m.Name+": missing module");if(!File.Exists(Paths.Asset(m.Image)))errors.Add(m.Name+": missing image");foreach(var c in m.Settings){controls++;choices+=c.Choices.Count;if(c.Kind!="number" && c.Choices.Count==0)errors.Add(m.Name+"/"+c.Key);if(c.Kind=="number" && c.Max<c.Min)errors.Add(m.Name+": range");}}string report="Modules: "+modules.Count+"\r\nControls: "+controls+"\r\nChoices: "+choices+"\r\nErrors: "+errors.Count+"\r\n"+string.Join("\r\n",errors);File.WriteAllText(args.Length>1?args[1]:Path.Combine(Paths.Root,"selftest.txt"),report);Environment.ExitCode=errors.Count==0?0:1;return;}
   if(args.Length>1 && args[0]=="/render"){Rendering=true;var f=new MainForm(modules,null);if(args.Length>2)f.SelectModule(args[2]);if(args.Length>3&&args[3]=="options")f.SelectOptions();UI.Render(f,args[1]);return;}
   if(args.Length>1 && args[0]=="/render-all"){Rendering=true;Directory.CreateDirectory(args[1]);int i=0;foreach(var m in modules){var f=new MainForm(modules,null);f.SelectModule(m.Name);UI.Render(f,Path.Combine(args[1],(i++).ToString("D2")+".png"));}return;}
   if(args.Length>1 && args[0]=="/render-advanced"){Rendering=true;Directory.CreateDirectory(args[1]);int i=0;foreach(var m in modules){if(m.Name=="Fish World"||m.Name=="Rainforest"||m.Name=="Slow Burn"||m.Name=="Swirling Magic"||m.Name=="Points of View")UI.Render(new AdvancedForm(m,new Dictionary<string,string>()),Path.Combine(args[1],(i++).ToString("D2")+".png"));}return;}
   bool first;using(var mutex=new Mutex(true,@"Local\AfterDarkClassic.Control",out first)){if(!first){using(var ev=EventWaitHandle.OpenExisting(@"Local\AfterDarkClassic.Show")){ev.Set();}return;}Application.Run(new Resident(modules,args.Length==0 || args[0]!="/tray"));}
  }catch(Exception ex){if(args.Length>1 && (args[0].StartsWith("/render")||args[0].EndsWith("test")))File.WriteAllText(args[1]+".error.txt",ex.ToString());else UI.Error(ex);Environment.ExitCode=1;}}
 }
 class Resident:ApplicationContext {
  NotifyIcon tray;MainForm panel;List<Module> modules;System.Windows.Forms.Timer timer;EventWaitHandle show;Process saver;
  public bool Enabled {get{return Paths.Int(WindowsSaver.Desktop,"ScreenSaveActive",Paths.Int(Paths.Modern,"Enabled",1))!=0;}set{WindowsSaver.Configure(Paths.Root,value,WindowsSaver.Seconds());Paths.Write(Paths.Modern,"Enabled",value?1:0);Refresh();}}
  public Resident(List<Module> list,bool open){modules=list;show=new EventWaitHandle(false,EventResetMode.AutoReset,@"Local\AfterDarkClassic.Show");tray=new NotifyIcon{Icon=Paths.GetIcon(),Text="After Dark",Visible=true};tray.DoubleClick+=(s,e)=>Open();Refresh();timer=new System.Windows.Forms.Timer{Interval=1000};timer.Tick+=(s,e)=>Tick();timer.Start();if(open)Open();}
  public void Refresh(){var menu=new ContextMenuStrip();menu.Items.Add("Abrir After Dark…",null,(s,e)=>Open());menu.Items.Add("Ejecutar ahora",null,(s,e)=>Run());var item=new ToolStripMenuItem("Activado"){Checked=Enabled};item.Click+=(s,e)=>Enabled=!Enabled;menu.Items.Add(item);var sound=new ToolStripMenuItem("Sonido"){Checked=Paths.Int(Paths.Legacy,"Mutesound",0)==0};sound.Click+=(s,e)=>{Paths.Write(Paths.Legacy,"Mutesound",sound.Checked?1:0);Refresh();};menu.Items.Add(sound);menu.Items.Add(new ToolStripSeparator());menu.Items.Add("Salir",null,(s,e)=>ExitThread());var old=tray.ContextMenuStrip;tray.ContextMenuStrip=menu;if(old!=null)old.Dispose();}
  public void Open(){if(panel==null||panel.IsDisposed){panel=new MainForm(modules,this);}else if(!panel.Visible)panel.SyncSelection();panel.Show();panel.WindowState=FormWindowState.Normal;panel.Activate();}
  void Tick(){if(show.WaitOne(0))Open();}
  public void Run(){try{if(panel!=null && panel.Visible && !panel.Save())return;if(panel!=null)panel.StopInline();string exe=Path.Combine(Paths.Root,"After Dark.scr");if(!File.Exists(exe))throw new IOException("Falta el motor After Dark.scr.");using(var k=Registry.LocalMachine.OpenSubKey(Paths.Machine)){string registered=k==null?"":Convert.ToString(k.GetValue("Path",""));if(!string.Equals(registered.TrimEnd('\\'),Paths.Root,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Instalá esta versión antes de ejecutar los salvapantallas. El motor original necesita registrar su carpeta.");}saver=Process.Start(new ProcessStartInfo(exe,"/s"){WorkingDirectory=Paths.Root,UseShellExecute=false});}catch(Exception ex){UI.Error(ex);}}
  protected override void ExitThreadCore(){timer.Stop();timer.Dispose();tray.Visible=false;tray.Dispose();show.Dispose();if(panel!=null)panel.Dispose();base.ExitThreadCore();}
 }
